const js=`const toggle=document.querySelector('.menu');toggle?.addEventListener('click',()=>{const n=document.querySelector('nav');n.classList.toggle('open');toggle.setAttribute('aria-expanded',n.classList.contains('open'))});document.querySelector('#quote')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),s=document.querySelector('#form-status');b.disabled=true;b.textContent='Submitting…';s.textContent='';try{let r=await fetch('/api/quote',{method:'POST',body:new FormData(f)});let d=await r.json();if(!r.ok)throw new Error(d.error||'Please try again.');f.reset();s.textContent='Your request is saved. Reference: '+d.reference+'. For time-sensitive help, call (916) 893-6280.';}catch(err){s.textContent=err.message+' You can also call (916) 893-6280.';}finally{b.disabled=false;b.textContent='Request my quote ↗';}});`;
function page(path){let [title,desc,body]=content(path);let schema={'@context':'https://schema.org','@type':'LocalBusiness',name:'Chem Kings Pool Service',url:origin,telephone:'+19168936280',email:'sacchemkings@gmail.com',logo:origin+'/assets/logo.png',areaServed:areas,sameAs:Object.values(links),description:'Pool cleaning, maintenance, equipment repair and spa service in Sacramento and surrounding communities.'};return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><meta name="description" content="${desc}"><link rel="canonical" href="${origin+path}"><meta name="theme-color" content="#101c25"><meta property="og:type" content="website"><meta property="og:site_name" content="Chem Kings Pool Service"><meta property="og:title" content="${title}"><meta property="og:description" content="${desc}"><meta property="og:url" content="${origin+path}"><meta property="og:image" content="${origin}/assets/share.jpg?v=brand2"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:image" content="${origin}/assets/share.jpg?v=brand2"><link rel="icon" href="/favicon.svg"><style>${css}</style><script type="application/ld+json">${JSON.stringify(schema)}</script></head><body><a href="#main" class="skip">Skip to content</a><div class="topbar"><div class="wrap">SACRAMENTO & SURROUNDING COMMUNITIES <span>LESS POOL WORK. MORE POOL DAYS.</span>${a('tel:+19168936280','(916) 893-6280')}</div></div><header class="header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="Chem Kings home">${crown}<div><strong>CHEM KINGS</strong><small>POOLS &amp; SPAS</small></div></a><button class="menu" aria-label="Toggle navigation" aria-controls="nav" aria-expanded="false">Menu ☰</button><nav id="nav" aria-label="Main navigation">${nav.map(([h,l])=>a(h,l)).join('')}${a('/contact/','Get a quote ↗','nav-cta')}</nav></div></header><main id="main">${body}</main><footer class="footer"><div class="wrap"><div class="footer-grid"><div><a href="/" class="brand">${crown}<div><strong>CHEM KINGS</strong><small>POOLS &amp; SPAS</small></div></a><p>Your pool. Our chemistry.<br>Pool and spa care for Sacramento and surrounding communities.</p>${a('tel:+19168936280','(916) 893-6280')}${a('mailto:sacchemkings@gmail.com','sacchemkings@gmail.com')}</div><div><h3>Pool & spa care</h3>${services.map(s=>a('/services/'+s[0]+'/',s[1])).join('')}</div><div><h3>Explore</h3>${nav.map(([h,l])=>a(h,l)).join('')}${a('/faq/','FAQs')}${a('/contact/','Request a quote')}</div><div><h3>Stay connected</h3>${Object.entries(links).map(([n,l])=>a(l,n+' ↗')).join('')}${a(google,'Google Maps ↗')}</div></div><div class="footer-bottom"><span>© 2026 Chem Kings Pool Service</span>${a('/privacy/','Privacy notice')}<span>Thoughtful care. Clearer water.</span></div><div class="preview-note">Website concept prepared for Chem Kings Pool Service. Pool imagery is illustrative. Service availability and quotations are confirmed directly.</div></div></footer><div class="mobile-bar">${a('tel:+19168936280','Call Chem Kings')}${a('/contact/','Get a quote ↗')}</div><script>${js}</script></body></html>`}


const routes=['/','/services/','/about/','/reviews/','/faq/','/contact/','/service-areas/','/privacy/',...services.map(s=>'/services/'+s[0]+'/'),...areas.map(s=>'/service-areas/'+slug(s)+'/')];
const json=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const safe=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function admin(){return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Chem Kings inquiry inbox</title><style>${css}body{padding:40px}.inbox{max-width:1000px;margin:auto}.inquiry{padding:24px;border:1px solid #ccc;margin:20px 0;background:white}.inquiry p{white-space:pre-wrap}input{max-width:420px}#results{margin-top:30px}</style></head><body><main class="inbox"><p class="eyebrow">CHEM KINGS · PRIVATE OPERATIONS</p><h1 style="font-size:48px">Service inquiries</h1><p>Enter the website inbox key to view requests. Keep this key private.</p><form id="login"><label>Inbox key<input type="password" id="key" required autocomplete="current-password"></label><button class="button">Open inbox</button></form><div id="results" role="status"></div></main><script>const out=document.querySelector('#results');document.querySelector('#login').onsubmit=async e=>{e.preventDefault();out.textContent='Loading…';try{const r=await fetch('/api/inquiries',{headers:{Authorization:'Bearer '+document.querySelector('#key').value}});const d=await r.json();if(!r.ok)throw Error(d.error);out.replaceChildren();const title=document.createElement('h2');title.textContent=d.inquiries.length+' requests';out.append(title);for(const x of d.inquiries){const card=document.createElement('article');card.className='inquiry';for(const [k,v] of Object.entries(x)){const p=document.createElement('p');p.textContent=k+': '+v;card.append(p)}out.append(card)}}catch(err){out.textContent=err.message}};</script></body></html>`}
export default {async fetch(req,env){const u=new URL(req.url);let path=u.pathname;
if(path==='/assets/logo.png')return new Response(Uint8Array.from(atob(assetData.logo),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/png','Cache-Control':'public,max-age=86400'}});
if(path==='/assets/pool.jpg'||path==='/assets/share.jpg'){const key=path.includes('share')?'og':'hero';return new Response(Uint8Array.from(atob(assetData[key]),c=>c.charCodeAt(0)),{headers:{'Content-Type':'image/jpeg','Cache-Control':'public,max-age=86400'}})}
if(path==='/favicon.svg')return new Response('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 480 480"><image href="data:image/png;base64,'+assetData.logo+'" width="480" height="480"/></svg>',{headers:{'Content-Type':'image/svg+xml'}});
if(path==='/robots.txt')return new Response('User-agent: *\nAllow: /\nDisallow: /admin/\nDisallow: /api/\nSitemap: '+origin+'/sitemap.xml',{headers:{'Content-Type':'text/plain'}});
if(path==='/sitemap.xml')return new Response('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+routes.map(p=>'<url><loc>'+origin+p+'</loc></url>').join('')+'</urlset>',{headers:{'Content-Type':'application/xml'}});
if(path==='/admin/'||path==='/admin')return new Response(admin(),{headers:{'Content-Type':'text/html;charset=utf-8','Cache-Control':'no-store','X-Robots-Tag':'noindex, nofollow'}});
if(path==='/api/inquiries'){if(!env.INBOX_KEY||req.headers.get('Authorization')!=='Bearer '+env.INBOX_KEY)return json({error:'Inbox key is incorrect.'},401);if(req.method!=='GET')return json({error:'Method not allowed'},405);let all=[],cursor;do{let list=await env.BUCKET.list({prefix:'inquiries/',limit:1000,cursor});all.push(...list.objects);cursor=list.truncated?list.cursor:undefined}while(cursor);all.sort((a,b)=>b.key.localeCompare(a.key));const selected=all.slice(0,200);let inquiries=await Promise.all(selected.map(async o=>JSON.parse(await(await env.BUCKET.get(o.key)).text())));return json({inquiries});}
if(path==='/api/quote'){if(req.method!=='POST')return json({error:'Method not allowed'},405);if(req.headers.get('Origin')&&req.headers.get('Origin')!==u.origin)return json({error:'Invalid request origin.'},403);if(Number(req.headers.get('Content-Length')||0)>12000)return json({error:'Your request is too long.'},413);let f;try{f=await req.formData()}catch{return json({error:'Please submit the contact form.'},400)}if(f.get('website'))return json({error:'Please call us to arrange your request.'},400);const val=k=>String(f.get(k)||'').trim();let record={name:val('name'),phone:val('phone'),email:val('email'),zip:val('zip'),service:val('service'),message:val('message')};if(!record.name||record.name.length>100||record.phone.length<7||record.phone.length>30||!/^\S+@\S+\.\S+$/.test(record.email)||record.email.length>160||!/^\d{5}$/.test(record.zip)||![...services.map(s=>s[1]),'Not sure yet'].includes(record.service)||record.message.length>2000||f.get('consent')!=='on')return json({error:'Check your contact information and consent, then try again.'},400);if(!env.BUCKET)return json({error:'Online requests are temporarily unavailable.'},503);
const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode((req.headers.get('CF-Connecting-IP')||record.email)+'|'+new Date().toISOString().slice(0,13)));const rateKey='rate/'+Array.from(new Uint8Array(hash)).map(x=>x.toString(16).padStart(2,'0')).join('');const prev=await env.BUCKET.get(rateKey);const count=prev?Number(await prev.text()):0;if(count>=5)return json({error:'Too many requests. Please call the team instead.'},429);await env.BUCKET.put(rateKey,String(count+1));const reference='CK-'+crypto.randomUUID().slice(0,8).toUpperCase();record={reference,submitted:new Date().toISOString(),...record};await env.BUCKET.put('inquiries/'+record.submitted+'-'+reference+'.json',JSON.stringify(record),{httpMetadata:{contentType:'application/json'}});if(req.headers.get('Accept')?.includes('text/html'))return new Response('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Request saved | Chem Kings</title><style>'+css+'</style></head><body><main class="wrap section"><h1>Request saved.</h1><p>Your reference is '+reference+'. For time-sensitive help, call (916) 893-6280.</p><a href="/" class="button">Return home</a></main></body></html>',{headers:{'Content-Type':'text/html;charset=utf-8','Cache-Control':'no-store'}});return json({ok:true,reference},201)}
if(!path.endsWith('/')&&!path.includes('.'))return Response.redirect(u.origin+path+'/',301);const found=routes.includes(path);return new Response(page(path),{status:found?200:404,headers:{'Content-Type':'text/html;charset=utf-8','X-Content-Type-Options':'nosniff','Referrer-Policy':'strict-origin-when-cross-origin','Permissions-Policy':'camera=(), microphone=(), geolocation=()','Cache-Control':'public,max-age=60'}});
}};
